WITH fn AS (SELECT p.oid,p.proname,p.proacl,p.proowner,pg_get_functiondef(p.oid) AS definition FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])'),to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])'))), checks AS (SELECT 'public_function_missing'::text AS audit_issue,'Thieu ham web dang goi'::text AS detail WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NULL UNION ALL SELECT 'legacy_core_missing','Thieu ham loi cu da duoc wrapper ngay 2026-07-22 bao quanh' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])') IS NULL UNION ALL SELECT 'product_guard_missing','Thieu hang rao kiem am theo tong ma hang' WHERE to_regprocedure('public.inventory_assert_no_negative_product_after(uuid,date)') IS NULL UNION ALL SELECT 'pre_fix_wrapper_not_calling_legacy_core','Ham public khong con goi legacy core; can doc lai dinh nghia live truoc khi chay fix' WHERE EXISTS(SELECT 1 FROM fn WHERE proname='inventory_soft_delete_manual_transactions' AND definition NOT ILIKE '%inventory_soft_delete_manual_transactions_core_20260722%') UNION ALL SELECT 'root_cause_not_present_in_legacy_core','Legacy core khong goi hang rao cu theo ma + khach; can dung lai va chan doan lai' WHERE EXISTS(SELECT 1 FROM fn WHERE proname='inventory_soft_delete_manual_transactions_core_20260722' AND definition NOT ILIKE '%inventory_assert_no_negative_after(%') UNION ALL SELECT 'public_can_execute','PUBLIC van co quyen goi ham huy kho' WHERE EXISTS(SELECT 1 FROM fn CROSS JOIN LATERAL aclexplode(COALESCE(fn.proacl,acldefault('f',fn.proowner))) acl WHERE fn.proname='inventory_soft_delete_manual_transactions' AND acl.grantee=0 AND acl.privilege_type='EXECUTE') UNION ALL SELECT 'anon_can_execute','anon van co quyen goi ham huy kho' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NOT NULL AND has_function_privilege('anon','public.inventory_soft_delete_manual_transactions(uuid[])','EXECUTE') UNION ALL SELECT 'authenticated_cannot_execute','authenticated khong goi duoc cong co hang rao dang nhap/quyen' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions(uuid[])') IS NOT NULL AND NOT has_function_privilege('authenticated','public.inventory_soft_delete_manual_transactions(uuid[])','EXECUTE') UNION ALL SELECT 'legacy_core_exposed_to_authenticated','authenticated dang goi truc tiep duoc legacy core' WHERE to_regprocedure('public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])') IS NOT NULL AND has_function_privilege('authenticated','public.inventory_soft_delete_manual_transactions_core_20260722(uuid[])','EXECUTE')), target AS (SELECT id,sku,name,customer_id FROM public.products WHERE sku='YT2618 SP 0304' AND deleted_at IS NULL), duplicate_candidates AS (SELECT t.id,t.tx_date::date AS tx_day,t.qty,t.note,t.customer_id,t.created_at,row_number() OVER(ORDER BY t.created_at DESC,t.id DESC) AS newest_rank FROM public.inventory_transactions t JOIN target p ON p.id=t.product_id WHERE t.deleted_at IS NULL AND t.adjusted_from_transaction_id IS NULL AND t.tx_type='in' AND t.tx_date::date='2026-07-17' AND t.qty=500), candidate AS (SELECT id,customer_id FROM duplicate_candidates WHERE newest_rank=1), checkpoint AS (SELECT ob.product_id,ob.period_month::date AS checkpoint_day,ob.opening_qty FROM public.inventory_opening_balances ob JOIN target p ON p.id=ob.product_id WHERE ob.deleted_at IS NULL AND ob.customer_id IS NULL AND ob.source_stocktake_id IS NOT NULL AND ob.period_month::date<='2026-07-17' ORDER BY ob.period_month DESC,ob.created_at DESC LIMIT 1), current_stock AS (SELECT p.id AS product_id,p.sku,p.name,c.checkpoint_day,c.opening_qty,c.opening_qty+COALESCE(sum(public.inventory_signed_effect(t.tx_type,t.qty,o.tx_type)),0) AS current_qty FROM target p JOIN checkpoint c ON c.product_id=p.id LEFT JOIN public.inventory_transactions t ON t.product_id=p.id AND t.deleted_at IS NULL AND t.tx_date::date>c.checkpoint_day AND t.tx_date::date<='2026-07-27' LEFT JOIN public.inventory_transactions o ON o.id=t.adjusted_from_transaction_id AND o.deleted_at IS NULL GROUP BY p.id,p.sku,p.name,c.checkpoint_day,c.opening_qty), correct_daily AS (SELECT t.tx_date::date AS tx_day,sum(public.inventory_signed_effect(t.tx_type,t.qty,o.tx_type)) AS delta FROM public.inventory_transactions t JOIN checkpoint c ON c.product_id=t.product_id LEFT JOIN public.inventory_transactions o ON o.id=t.adjusted_from_transaction_id AND o.deleted_at IS NULL WHERE t.deleted_at IS NULL AND t.id<>(SELECT id FROM candidate) AND t.tx_date::date>c.checkpoint_day AND t.tx_date::date<='2026-07-27' GROUP BY t.tx_date::date), correct_running AS (SELECT d.tx_day,d.delta,c.opening_qty+sum(d.delta) OVER(ORDER BY d.tx_day) AS running_qty FROM correct_daily d CROSS JOIN checkpoint c), customer_opening AS (SELECT COALESCE((SELECT ob.opening_qty FROM public.inventory_opening_balances ob JOIN target p ON p.id=ob.product_id JOIN candidate c ON ob.customer_id IS NOT DISTINCT FROM c.customer_id WHERE ob.deleted_at IS NULL AND ob.period_month::date<='2026-07-17' ORDER BY ob.period_month DESC,ob.created_at DESC LIMIT 1),0) AS opening_qty), legacy_daily AS (SELECT t.tx_date::date AS tx_day,sum(public.inventory_signed_effect(t.tx_type,t.qty,o.tx_type)) AS delta FROM public.inventory_transactions t JOIN target p ON p.id=t.product_id JOIN candidate c ON t.customer_id IS NOT DISTINCT FROM c.customer_id LEFT JOIN public.inventory_transactions o ON o.id=t.adjusted_from_transaction_id AND o.deleted_at IS NULL WHERE t.deleted_at IS NULL AND t.id<>c.id GROUP BY t.tx_date::date), legacy_running AS (SELECT d.tx_day,d.delta,c.opening_qty+sum(d.delta) OVER(ORDER BY d.tx_day) AS running_qty FROM legacy_daily d CROSS JOIN customer_opening c), output AS (SELECT 10 AS sort_order,'function_audit'::text AS section,jsonb_build_object('status',CASE WHEN EXISTS(SELECT 1 FROM checks) THEN 'STOP' ELSE 'OK' END,'problems',COALESCE((SELECT jsonb_agg(jsonb_build_object('issue',audit_issue,'detail',detail) ORDER BY audit_issue) FROM checks),'[]'::jsonb)) AS detail UNION ALL SELECT 20,'duplicate_candidates',jsonb_build_object('product',COALESCE((SELECT jsonb_build_object('sku',sku,'name',name,'current_customer_id',customer_id) FROM target),'null'::jsonb),'rows',COALESCE((SELECT jsonb_agg(jsonb_build_object('transaction_id',id,'tx_day',tx_day,'qty',qty,'note',note,'customer_id',customer_id,'created_at',created_at,'review_note',CASE WHEN newest_rank=1 THEN 'Dong tao sau; chi la ung vien nhap trung, chu du an phai xac nhan truoc khi huy' ELSE 'Dong tao truoc' END) ORDER BY created_at) FROM duplicate_candidates),'[]'::jsonb)) UNION ALL SELECT 30,'active_opening_balances',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',ob.id,'period_month',ob.period_month,'opening_qty',ob.opening_qty,'customer_id',ob.customer_id,'source_stocktake_id',ob.source_stocktake_id,'created_at',ob.created_at) ORDER BY ob.period_month,ob.created_at) FROM public.inventory_opening_balances ob JOIN target p ON p.id=ob.product_id WHERE ob.deleted_at IS NULL),'[]'::jsonb) UNION ALL SELECT 40,'current_product_stock',COALESCE((SELECT to_jsonb(s) FROM current_stock s),'null'::jsonb) UNION ALL SELECT 50,'correct_product_guard_after_hypothetical_cancel',COALESCE((SELECT jsonb_agg(jsonb_build_object('tx_day',tx_day,'delta',delta,'running_qty',running_qty) ORDER BY tx_day) FROM correct_running WHERE tx_day>='2026-07-11'),'[]'::jsonb) UNION ALL SELECT 60,'legacy_customer_guard_after_hypothetical_cancel',COALESCE((SELECT jsonb_agg(jsonb_build_object('tx_day',tx_day,'delta',delta,'running_qty',running_qty) ORDER BY tx_day) FROM legacy_running WHERE tx_day>='2026-07-11'),'[]'::jsonb)) SELECT section,detail FROM output ORDER BY sort_order;
